// Dynamically generate departments from employee data
export const departments: Department[] = (() => {
  const deptMap = new Map<string, { count: number; head: string }>();
  
  employees.forEach(emp => {
    const dept = emp.department;
    if (dept && dept !== "N/A" && dept !== "Executive") {
      const existing = deptMap.get(dept);
      if (existing) {
        existing.count++;
      } else {
        deptMap.set(dept, { count: 1, head: emp.reportingTo !== "N/A" ? emp.reportingTo : emp.name });
      }
    }
  });
  
  return Array.from(deptMap.entries())
    .map(([name, data]) => ({
      name,
      employeeCount: data.count,
      head: data.head
    }))
    .sort((a, b) => b.employeeCount - a.employeeCount);
})();
